def uniform_rects(arr,thick=1):
    H,W=arr.shape; res=[]
    for oh in range(2,H):
        for ow in range(2,W):
            for rr in range(H-oh+1):
                for cc in range(W-ow+1):
                    bd=tuple(s[0,:].tolist())
                    bot=tuple(s[-1,:].tolist())
                    left=tuple(s[:,0].tolist())
                    right=tuple(s[:,-1].tolist())
                    if len({bd,bot,left,right})==1:
                        val=int(list({bd,bot,left,right})[0])
                        # all neighbors just outside border must differ from val
                        ok=True
                        for r in range(rr-1,rr+oh+1):
                            for c in range(cc-1,cc+ow+1):
                                if (r==rr or c==cc) and 0<=r<H and 0<=c<W: continue
                                if r>=rr-1 and r<=rr+oh and cc<=c<cc+ow: continue
                                if r==rr and cc<=c<cc+ow or r==rr+oh and cc<=c<cc+ow or (rr<=r<rr+oh and c==cc or c==cc+ow-1): pass
                                pass
                        # simple: count cells adjacent to border (8-neighborhood outside ring) that equal val -> must be 0
                        outadj=[ (r,c) for r in range(max(0,rr-1),H) for c in range(max(0,cc-1),W) 
                               if ((rr<=r<rr+oh and c==cc-1) or (rr<=r<rr+oh and c==cc+ow) or (r==rr-1 and cc<=c<cc+ow) or (r==rr+oh and cc<=c<cc+ow))]
