def connected_components(arr):
    H,W=arr.shape; seen=np.zeros_like(arr,bool); comps=[]
    for i in range(H):
        for j in range(W):
            if arr[i,j]!=0 and not seen[i,j]:
                col=arr[i,j]; st=[(i,j)]; seen[i,j]=True; cells=[]
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<W and not seen[nr,nc] and arr[nr,nc]==col:
                                seen[nr,nc]=True; st.append((nr,nc))
                comps.append((len(cells),col))
    return comps
