def diff_region(A,O):
    H,W=A.shape; h_,w_=O.shape
    best=None
    for i in range(H-h_+1):
        for j in range(W-w_+1):
            s=sum(1 for r in range(h_) for c in range(w_) if A[i+r,j+c]!=O[r,c])
