def find_all_solid(A,bg):
    H,W=A.shape; best=[]
    for C in set(collections.Counter(A.flat))-{bg}:
        mask=(A==C)
        # maximal filled rectangles of color C: run over each row run lengths then grow down
        for ii in range(H):
            runs=[]
            col=mask[ii,:].tolist(); L=len(col)
            j=0; cnt=0
            while j<L:
                if col[j]:
                    start=j
                    while j<L and col[j]: j+=1; cnt+=1
                    runs.append((start,j-start))
                else: j+=1
            for (start,length) in runs:
                h=length-1
                good=True
                i=start+h
                while i<H:
                    rowcol=mask[i,start:start+length]
                    if not rowcol.all(): good=False; break
                    i+=1
                if good and h>=1: best.append((C,ii,start,h,length))
    return best
