def match_info(A,O):
    A=np.array(A); O=np.array(O)
    bo=int(O[0,0]); oH,oW=O.shape
    info=[]
    H,W=A.shape
    for hh in range(2,H+1):
        for ww in range(2,W+1):
            for ii in range(H-hh+1):
                for jj in range(W-ww+1):
                    sub=A[ii:ii+hh,jj:jj+ww]
                    C=sub[0,0]
                    if set([sub[0,0],sub[0,-1],sub[-1,0],sub[-1,-1]])!=set([C]): continue
                    bd_uniform=all(sub[i,j]==C for i in range(hh) for j in range(ww) if i in (0,hh-1) or j in (0,ww-1))
                    if not bd_uniform: continue
                    f_cells=[(i-jj,jj+j) for i in range(ii+1,ii+hh-1) for j in range(jj+1,jj+ww-1) if A[ii+i,jj+j]!=C]
                    if not f_cells: continue
                    info.append((C,(ii,jj,hh,ww),f_cells))
    return info

